import{_ as a,c as e,o as r,a4 as i}from"./chunks/framework.4aTu-Nia.js";const u=JSON.parse('{"title":"画图","description":"","frontmatter":{},"headers":[],"relativePath":"project/draw.md","filePath":"project/draw.md"}'),l={name:"project/draw.md"},t=i('<h1 id="画图" tabindex="-1">画图 <a class="header-anchor" href="#画图" aria-label="Permalink to &quot;画图&quot;">​</a></h1><h2 id="流程图" tabindex="-1">流程图 <a class="header-anchor" href="#流程图" aria-label="Permalink to &quot;流程图&quot;">​</a></h2><h3 id="why" tabindex="-1">why <a class="header-anchor" href="#why" aria-label="Permalink to &quot;why&quot;">​</a></h3><ul><li>核心部件、主流程，有一定复杂度，影响系统稳健性</li><li>便于交接或快速回忆</li></ul><blockquote><p>流程图这方面我们研发部内部也做了讨论，最终决定需要用流程图来表述一些复杂、关键的状态转换。几个理由：1. 有些需要讨论采用哪种技术方案，避免走冤枉路。用流程图方便项目经理、程序员、市场经理三方共同讨论。这种流程图是粗线条的式的。2. 部分复杂、影响系统稳健性的逻辑，程序员需要画出流程，避免漏洞。编写、审核代码就有了依据。3. N年后再修改代码，有个流程图便于快速回忆主体逻辑。4. 代码移交。 当然流程图不能解决所有问题，有些不方便用流程图表述的，用文字、伪代码、波形图等手段。</p></blockquote><h3 id="how" tabindex="-1">how <a class="header-anchor" href="#how" aria-label="Permalink to &quot;how&quot;">​</a></h3><p>要点：</p><ul><li>通常用椭圆形表示开始和结束</li><li>标明类型，如 <code>ui: enter page</code>，<code>store: set id</code>，<code>c++: encode img</code></li><li>平行流程，建立关系</li></ul><p>步骤：</p><ol><li>确定目的，确定开始和结束</li><li>识别主要步骤、决策，并连接</li><li>检查并修正</li><li>选择画图工具绘制（这是最后要做的事）</li></ol><h2 id="时序图" tabindex="-1">时序图 <a class="header-anchor" href="#时序图" aria-label="Permalink to &quot;时序图&quot;">​</a></h2><ul><li>不是太好用 <a href="https://www.websequencediagrams.com/" target="_blank" rel="noreferrer">WebSequenceDiagrams - Draw UML sequence diagrams online in seconds</a></li><li>mermaid typora</li><li>github 支持</li><li>gpt 生成</li></ul><h2 id="think" tabindex="-1">Think <a class="header-anchor" href="#think" aria-label="Permalink to &quot;Think&quot;">​</a></h2><p>画图很麻烦</p><p>理清、返工</p><p>提前把主干理清楚</p><p>mermaid 自己看没问题，有些问题需要规避</p><p><a href="https://www.iminho.me/wiki/docs/mindoc/mermaid.md" target="_blank" rel="noreferrer">基于 Mermaid 的时序图、流程图和甘特图 - Powered by MinDoc</a><a href="https://mermaidjs.github.io/mermaid-live-editor/#/edit/eyJjb2RlIjoiZ3JhcGggVERcbkFbQ2hyaXN0bWFzXSAtLT58R2V0IG1vbmV5fCBCKEdvIHNob3BwaW5nKVxuQiAtLT4gQ3tMZXQgbWUgdGhpbmt9XG5DIC0tPnxPbmV8IERbTGFwdG9wXVxuQyAtLT58VHdvfCBFW2lQaG9uZV1cbkMgLS0-fFRocmVlfCBGW2ZhOmZhLWNhciBDYXJdXG4iLCJtZXJtYWlkIjp7InRoZW1lIjoiZGVmYXVsdCJ9fQ" target="_blank" rel="noreferrer">Online FlowChart &amp; Diagrams Editor - Mermaid Live Editor</a><a href="https://www.123si.org/javascript/article/markdown-flow-chart-flowchart-js/" target="_blank" rel="noreferrer">Markdown 流程图 flowchart.js - JavaScript - 123si 博客</a></p><p>时序图+流程图，带拼写提示 <a href="http://chartmage.com/index.html" target="_blank" rel="noreferrer">Chart Mage - Draw sequence diagrams and flowcharts at lightning speed.</a></p><h2 id="技巧" tabindex="-1">技巧 <a class="header-anchor" href="#技巧" aria-label="Permalink to &quot;技巧&quot;">​</a></h2><ul><li>元素：图形 链接 文本</li><li>悬浮有操作提示</li><li>对齐，可以先连上箭头，然后把不齐的图形用箭头微移</li><li>使用cmd + click(鼠标左键点击)来进行特定元素的多选</li><li>替换，drag 直到 替换图标（褐色） 出现</li><li>可以先不处理样式，做完后统一选择处理</li><li>样式都可以后期改，比如线的箭头，粗细</li></ul><p><a href="https://github.com/jgraph/drawio-desktop/releases" target="_blank" rel="noreferrer">Releases · jgraph/drawio-desktop</a> 桌面端，不支持打开线上文件？</p><p><a href="https://juejin.im/entry/5acc5205f265da2391487073" target="_blank" rel="noreferrer">使用draw.io绘制简洁大方的流程图 - 开发工具 - 掘金</a></p><h2 id="draw-io" tabindex="-1">draw.io <a class="header-anchor" href="#draw-io" aria-label="Permalink to &quot;draw.io&quot;">​</a></h2><p>高级图形：flow|tree|mindmap</p><p>自动添加并连接到已选中图形</p><ol><li>选中图形</li><li>按住 alt，同时点击待添加图形 <img src="https://img.oaker.bid/?url=http://ww2.sinaimg.cn/mw690/4e5d3ea7ly1h0fjgqljw7j20z80g2aeg.jpg" alt="image.png"></li></ol><p>全选，样式里设置 sketch，设置框架主题</p><p>右键批量选择线条或是图形</p><p>style -&gt; 复制样式、粘贴样式</p><h3 id="数据" tabindex="-1">数据 <a class="header-anchor" href="#数据" aria-label="Permalink to &quot;数据&quot;">​</a></h3><p>xml 是原始格式</p><h3 id="离线能力" tabindex="-1">离线能力 <a class="header-anchor" href="#离线能力" aria-label="Permalink to &quot;离线能力&quot;">​</a></h3><p>部分功能不可用，如</p><ul><li>导出到网盘</li><li>转换格式</li></ul><p><a href="https://drawio.freshdesk.com/support/solutions/articles/16000067668-run-diagrams-net-offline" target="_blank" rel="noreferrer">Run diagrams.net offline : draw.io is becoming diagrams.net</a></p><h2 id="ref" tabindex="-1">ref <a class="header-anchor" href="#ref" aria-label="Permalink to &quot;ref&quot;">​</a></h2><p><a href="https://www.bmpi.dev/self/my-drawing-toolbox/" target="_blank" rel="noreferrer">我的绘图工具箱 · 构建我的被动收入</a></p><h2 id="白板" tabindex="-1">白板 <a class="header-anchor" href="#白板" aria-label="Permalink to &quot;白板&quot;">​</a></h2><p><a href="https://excalidraw.com/" target="_blank" rel="noreferrer">Excalidraw | Hand-drawn look &amp; feel • Collaborative • Secure</a></p><h2 id="架构图" tabindex="-1">架构图 <a class="header-anchor" href="#架构图" aria-label="Permalink to &quot;架构图&quot;">​</a></h2><ul><li>思考：业务关系，分层</li><li>自下而上：支撑，抽象</li><li>布局：左右，左右下</li><li>步骤： 1. 分层 2. 分模块 3. 填功能</li></ul><p>步骤：</p><ol><li><p><strong>标识主要组件：</strong> 确定系统中的主要组件。这可能包括前端应用、后端服务、数据库、第三方服务等。用简单的图形符号来表示每个组件。</p></li><li><p><strong>连接组件：</strong> 用箭头或线条连接组件，表示它们之间的关系和通信。这可以包括数据流、API调用、消息传递等。标明连接线的方向，以表示信息流向。</p></li><li><p><strong>标明接口和协议：</strong> 如果组件之间有定义的接口和协议，确保在图中标注清楚。这有助于理解组件之间的通信方式。</p></li><li><p><strong>标注重要属性：</strong> 对于每个组件，标注关键的属性，例如技术栈、版本号、数据库类型等。这有助于更详细地了解系统的技术细节。</p></li><li><p><strong>分层表示：</strong> 如果系统有多个层次（例如前端、后端、数据库层等），可以考虑使用分层表示。这使得架构图更易于理解。</p></li></ol><p><a href="https://my.oschina.net/yuque/blog/5517347" target="_blank" rel="noreferrer">如何用语雀画板，轻松画出架构图？ - 语雀的个人空间 - OSCHINA - 中文开源技术交流社区</a></p>',45),o=[t];function n(h,d,s,p,c,m){return r(),e("div",null,o)}const g=a(l,[["render",n]]);export{u as __pageData,g as default};
